	// swap and future
	//
	//     {
	//         "code": "00000",
	//         "msg": "success",
	//         "requestTime": 1700290724614,
	//         "data": [
	//             {
	//                 "symbol": "BTCUSDT",
	//                 "level": "1",
	//                 "startUnit": "0",
	//                 "endUnit": "150000",
