func (this *Bitget) ParseLedgerEntry(item any, optionalArgs ...any) any {
	//
	// spot
	//
	//     {
	//         "billId": "1111506298997215233",
	//         "coin": "USDT",
	//         "groupType": "transfer",
	//         "businessType": "transfer_out",
	//         "size": "-11.64958799",
	//         "balance": "0.00000000",
	//         "fees": "0.00000000",
	//         "cTime": "1700729673028"
	//     }
	//
	// swap and future
	//
	//     {
	//         "billId": "1111499428100472833",
	//         "symbol": "",
	//         "amount": "-11.64958799",
	//         "fee": "0",
	//         "feeByCoupon": "",
	//         "businessType": "trans_to_exchange",
	//         "coin": "USDT",
	//         "cTime": "1700728034996"
	//     }
	//
	// uta financial records
	//
	//     {
	//         "category": "Margin",
	//         "id": "13111111111111111",
	//         "symbol": "BTCUSDT",
	//         "coin": "BTC",
	//         "type": "ORDER_DEALT_IN",
	//         "positionType": "crossed",
	//         "fee": "-0.00000531",
	//         "positionAmount": "0.001",
	//         "positionBalance": "0.001",
	//         "amount": "0.00531168",
	//         "balance": "55.10017801",
	//         "ts": "1745853486185"
	//     }
	//
	// uta funding financial records
	//
	//     {
	//         "id": "1477183363639320585",
	//         "coin": "USDT",
	//         "groupType": "transfer",
	//         "type": "transfer_out",
	//         "amount": "-30.00000000",
	//         "balance": "0.00000000",
	//         "ts": "1787913879280"
	//     }
	//
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var currencyId *string = this.SafeString(item, "coin")
	var code *string = this.SafeCurrencyCode(currencyId, currency)
	currency = MapTyped(this.SafeCurrency(currencyId, currency))
	var timestamp *int64 = this.SafeInteger2(item, "cTime", "ts")
	var balanceString *string = this.SafeString(item, "balance")
	var after *float64 = Float64PtrTyped(this.ParseNumber(balanceString))
	var feeCostString *string = this.SafeString2(item, "fees", "fee")
	var feeCost any = nil
	if feeCostString != nil {
		feeCost = this.ParseNumber(Precise.StringAbs(feeCostString)) // deliberate for both generations, uta reports charged fees as negative values and the v2 fields hold signed values too
	}
	var amountRaw *string = this.SafeString2(item, "size", "amount", "")
	var amount *float64 = Float64PtrTyped(this.ParseNumber(Precise.StringAbs(amountRaw)))
	var before any = nil
	if (balanceString != nil) && (amountRaw == nil || *amountRaw != "") {
		before = this.ParseNumber(Precise.StringSub(balanceString, amountRaw)) // subtract the signed change from the after-balance, the base derivation assumes a signed amount and would produce a negative before on outflows
	}
	var direction string = "in"
	if func() int {
		if amountRaw == nil {
			return -1
		}
		return strings.Index(*amountRaw, "-")
	}() >= 0 {
		direction = "out"
	}
	return this.SafeLedgerEntry(map[string]any{
		"info":             item,
		"id":               this.SafeString2(item, "billId", "id"),
		"timestamp":        timestamp,
		"datetime":         this.Iso8601(timestamp),
		"direction":        direction,
		"account":          nil,
		"referenceId":      nil,
		"referenceAccount": nil,
		"type":             this.ParseLedgerType(this.SafeStringN(item, []any{"businessType", "groupType", "type"})),
		"currency":         code,
		"amount":           amount,
		"before":           before,
		"after":            after,
		"status":           nil,
		"fee": map[string]any{
			"currency": code,
			"cost":     feeCost,
		},
	}, currency)
}
