		response = MapTyped(PanicOnError((<-this.PublicMixGetV2MixMarketHistoryFundRate(this.Extend(request, params))).Raw))
		//
		//     {
		//         "code": "00000",
		//         "msg": "success",
		//         "requestTime": 1652406728393,
