func (this *Bitget) fetchFundingHistoryBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var symbol *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = symbol
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	params := GetArg(optionalArgs, 3, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	if symbol == nil {
		panic(ArgumentsRequired(this.Id + " fetchFundingHistory() requires a symbol argument"))
	}
	var uta any = nil
	var utaparamsVariable []any = ListTyped(PanicOnError((<-this.HandleUTAAndParamsAsync(params, "fetchFundingHistory", false))))
	uta = GetValue(utaparamsVariable, 0)
	params = GetValue(utaparamsVariable, 1)
	var paginate bool = false
	var paginateparamsVariable []any = this.HandleOptionAndParams(params, "fetchFundingHistory", "paginate")
	paginate = GetValueBool(paginateparamsVariable, 0, false)
	params = GetValue(paginateparamsVariable, 1)
	if paginate {
		if uta == true {

			var retRes963923 []any = ListTyped(PanicOnError((<-this.FetchPaginatedCallCursorAsync("fetchFundingHistory", symbol, since, limit, params, "cursor", "cursor"))))
			ch <- BoxAbsent(retRes963923)
			return nil
		}

		var retRes964119 []any = ListTyped(PanicOnError((<-this.FetchPaginatedCallCursorAsync("fetchFundingHistory", symbol, since, limit, params, "endId", "idLessThan"))))
		ch <- BoxAbsent(retRes964119)
		return nil
	}
	var market map[string]any = MapTyped(this.Market(symbol))
	if GetValue(market, "swap") != true {
		panic(BadSymbol(this.Id + " fetchFundingHistory() supports swap contracts only"))
	}
	var productType any = nil
	productTypeparamsVariable := this.HandleProductTypeAndParams(market, params)
	productType = GetValue(productTypeparamsVariable, 0)
	params = GetValue(productTypeparamsVariable, 1)
	var request map[string]any = map[string]any{}
	var requestparamsVariable []any = this.HandleUntilOption("endTime", request, params)
	request = MapTyped(GetValue(requestparamsVariable, 0))
	params = GetValue(requestparamsVariable, 1)
	if since != nil {
		request["startTime"] = since
	}
	if limit != nil {
		request["limit"] = limit
	}
	var response map[string]any = nil
	if uta == true {
		request["coin"] = market["settleId"]
		request["category"] = productType

		response = MapTyped(PanicOnError((<-this.PrivateUtaGetV3AccountFinancialRecords(this.Extend(request, params))).Raw))
	} else {
		request["symbol"] = market["id"]
		request["marginCoin"] = market["settleId"]
		request["businessType"] = "contract_settle_fee"
		request["productType"] = productType

		response = MapTyped(PanicOnError((<-this.PrivateMixGetV2MixAccountBill(this.Extend(request, params))).Raw))
	}
	var data map[string]any = SafeMapTyped(response, "data")
	var bills any = this.SafeList2(data, "bills", "list", []any{})
	if uta == true {
		bills = this.FilterByArray(bills, "type", []any{"CONTRACT_MAIN_SETTLE_FEE_USER_IN", "CONTRACT_MAIN_SETTLE_FEE_USER_OUT"}, false)
	}

	ch <- this.ParseFundingHistories(bills, market, since, limit)
	return nil
}
func (this *Bitget) ParseFundingHistory(contract any, optionalArgs ...any) any {
	//
	//     {
	//         "billId": "1111499428100472833",
	//         "symbol": "BTCUSDT",
	//         "amount": "-0.004992",
	//         "fee": "0",
	//         "feeByCoupon": "",
	//         "businessType": "contract_settle_fee",
	//         "coin": "USDT",
	//         "cTime": "1700728034996"
	//     }
	//
	//     {
	//         "category": "Margin",
	//         "id": "13111111111111111",
	//         "symbol": "BTCUSDT",
	//         "coin": "BTC",
	//         "type": "ORDER_DEALT_IN",
	//         "amount": "0.00531168",
	//         "fee": "-0.00000531",
	//         "balance": "55.10017801",
	//         "ts": "1745853486185"
	//     }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var marketId *string = this.SafeString(contract, "symbol")
	var currencyId *string = this.SafeString(contract, "coin")
	var timestamp *int64 = this.SafeInteger2(contract, "cTime", "ts")
	return map[string]any{
		"info":      contract,
		"symbol":    this.SafeSymbol(marketId, market, nil, "swap"),
		"timestamp": timestamp,
		"datetime":  this.Iso8601(timestamp),
		"code":      this.SafeCurrencyCode(currencyId),
		"amount":    this.SafeNumber(contract, "amount"),
		"id":        this.SafeString2(contract, "billId", "id"),
	}
}
func (this *Bitget) ParseFundingHistories(contracts any, optionalArgs ...any) any {
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var result []any = []any{}
	for i := 0; i < GetArrayLength(contracts); i++ {
		var contract any = GetValue(contracts, i)
		// for non-uta, we've set bussinessType in request payload. Not sure why this existed.
		// const business = this.safeString (contract, 'businessType');
		// if (business !== 'contract_settle_fee') {
		//     continue;
		// }
		result = append(result, this.ParseFundingHistory(contract, market))
	}
	var sorted []any = this.SortBy(result, "timestamp")
	var symbol any = nil
	if market != nil {
		symbol = GetValue(market, "symbol")
	}
	return this.FilterBySymbolSinceLimit(sorted, symbol, since, limit)
}
