func (this *Bitget) ParseOpenInterest(interest any, optionalArgs ...any) any {
	//
	// default
	//
	//     {
	//         "openInterestList": [
	//             {
	//                 "symbol": "BTCUSDT",
	//                 "size": "52234.134"
	//             }
	//         ],
	//         "ts": "1700866041023"
	//     }
	//
	// uta
	//
	//     {
	//         "list": [
	//             {
	//                 "symbol": "BTCUSDT",
	//                 "openInterest": "18166.3583"
	//             }
	//         ],
	//         "ts": "1751101220993"
	//     }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var data []any = SafeList2Typed(interest, "openInterestList", "list")
	var timestamp *int64 = this.SafeInteger(interest, "ts")
	var marketId *string = this.SafeString(func() any {
		if 0 >= 0 && 0 < len(data) {
			return DerefScalar(data[0])
		}
		return nil
	}(), "symbol")
	return this.SafeOpenInterest(map[string]any{
		"symbol": this.SafeSymbol(marketId, market, nil, "contract"),
		"openInterestAmount": this.SafeNumber2(func() any {
			if 0 >= 0 && 0 < len(data) {
				return DerefScalar(data[0])
			}
			return nil
		}(), "size", "openInterest"),
		"openInterestValue": nil,
		"timestamp":         timestamp,
		"datetime":          this.Iso8601(timestamp),
		"info":              interest,
	}, market)
}

/**
 * @method
 * @name bitget#fetchTransfers
 * @description fetch a history of internal transfers made on an account
 * @see https://www.bitget.com/api-doc/spot/account/Get-Account-TransferRecords
 * @param {string} code unified currency code of the currency transferred
 * @param {int} [since] the earliest time in ms to fetch transfers for
 * @param {int} [limit] the maximum number of transfers structures to retrieve
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {int} [params.until] the latest time in ms to fetch entries for
 * @returns {object[]} a list of [transfer structures]{@link https://docs.ccxt.com/?id=transfer-structure}
 */
func (this *Bitget) FetchTransfersAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchTransfersBody(ch, optionalArgs...)
	return ch
}
func (this *Bitget) fetchTransfersBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var code *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = code
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if code == nil {
		panic(ArgumentsRequired(this.Id + " fetchTransfers() requires a code argument"))
	}
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var typeVar any = nil
	var typeVarparamsVariable []any = this.HandleMarketTypeAndParams("fetchTransfers", nil, params)
	typeVar = GetValue(typeVarparamsVariable, 0)
	params = MapTyped(GetValue(typeVarparamsVariable, 1))
	var fromAccount *string = this.SafeString(params, "fromAccount", typeVar)
	params = MapTyped(this.Omit(params, "fromAccount"))
	var accountsByType map[string]any = SafeMapTyped(this.Options, "accountsByType")
	typeVar = DerefScalar(this.SafeString(accountsByType, fromAccount))
	var currency map[string]any = MapTyped(this.Currency(code))
	var request map[string]any = map[string]any{
		"coin":     currency["id"],
		"fromType": typeVar,
	}
	if since != nil {
		request["startTime"] = since
	}
	if limit != nil {
		request["limit"] = limit
	}
	var requestparamsVariable []any = this.HandleUntilOption("endTime", request, params)
	request = MapTyped(GetValue(requestparamsVariable, 0))
	params = MapTyped(GetValue(requestparamsVariable, 1))

	var response map[string]any = MapTyped(PanicOnError((<-this.PrivateSpotGetV2SpotAccountTransferRecords(this.Extend(request, params))).Raw))
	//
	//     {
	//         "code": "00000",
	//         "msg": "success",
	//         "requestTime": 1700873854651,
	//         "data": [
	//             {
	//                 "coin": "USDT",
	//                 "status": "Successful",
	//                 "toType": "crossed_margin",
	//                 "toSymbol": "",
	//                 "fromType": "spot",
	//                 "fromSymbol": "",
	//                 "size": "11.64958799",
	//                 "ts": "1700729673028",
	//                 "clientOid": "1111506298504744960",
	//                 "transferId": "24930940"
	//             },
	//         ]
	//     }
	//
	var data []any = SafeListTypedDefault(response, "data", []any{})

	ch <- this.ParseTransfers(data, currency, since, limit)
	return nil
}

/**
 * @method
 * @name bitget#transfer
 * @description transfer currency internally between wallets on the same account
 * @see https://www.bitget.com/api-doc/spot/account/Wallet-Transfer
 * @see https://www.bitget.com/api-doc/uta/account/transfer
 * @param {string} code unified currency code
 * @param {float} amount amount to transfer
 * @param {string} fromAccount account to transfer from
 * @param {string} toAccount account to transfer to
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {boolean} [params.uta] set to true to transfer via the unified trading account v3 endpoint
 * @param {string} [params.symbol] unified CCXT market symbol, required when transferring to or from an account type that is a leveraged position-by-position account
 * @param {string} [params.clientOid] custom id
 * @returns {object} a [transfer structure]{@link https://docs.ccxt.com/?id=transfer-structure}
 */
func (this *Bitget) TransferAsync(code any, amount any, fromAccount any, toAccount any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.transferBody(ch, code, amount, fromAccount, toAccount, optionalArgs...)
	return ch
}
func (this *Bitget) transferBody(ch chan any, code any, amount any, fromAccount any, toAccount any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	params := GetArg(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var uta any = nil
	var utaparamsVariable []any = ListTyped(PanicOnError((<-this.HandleUTAAndParamsAsync(params, "transfer", false))))
	uta = GetValue(utaparamsVariable, 0)
	params = GetValue(utaparamsVariable, 1)
	var currency map[string]any = MapTyped(this.Currency(code))
	var accountsByType map[string]any = SafeMapTyped(this.Options, "accountsByType")
	var fromType *string = this.SafeString(accountsByType, fromAccount)
	var toType *string = this.SafeString(accountsByType, toAccount)
	var request map[string]any = map[string]any{
		"fromType": fromType,
		"toType":   toType,
		"amount":   amount,
		"coin":     currency["id"],
	}
	var symbol *string = this.SafeString(params, "symbol")
	params = this.Omit(params, "symbol")
	var market map[string]any = nil
	if symbol != nil {
		market = this.Market(symbol)
		request["symbol"] = GetValue(market, "id")
	}
	var response map[string]any = nil
	if uta == true {

		response = MapTyped(PanicOnError((<-this.PrivateUtaPostV3AccountTransfer(this.Extend(request, params))).Raw))
	} else {

		response = MapTyped(PanicOnError((<-this.PrivateSpotPostV2SpotWalletTransfer(this.Extend(request, params))).Raw))
	}
	//
	//     {
	//         "code": "00000",
	//         "msg": "success",
	//         "requestTime": 1700874302021,
	//         "data": {
	//             "transferId": "1112112916581847040",
	//             "clientOrderId": null
	//         }
	//     }
	//
	var data any = this.SafeDict(response, "data", map[string]any{})
	AddElementToObject(data, "ts", this.SafeInteger(response, "requestTime"))

	ch <- this.ParseTransfer(data, currency)
	return nil
}
func (this *Bitget) ParseTransfer(transfer any, optionalArgs ...any) any {
	//
	// transfer
	//
	//     {
	//         "transferId": "1112112916581847040",
	//         "clientOrderId": null,
	//         "ts": 1700874302021
	//     }
	//
	// fetchTransfers
	//
	//     {
	//         "coin": "USDT",
	//         "status": "Successful",
	//         "toType": "crossed_margin",
	//         "toSymbol": "",
	//         "fromType": "spot",
	//         "fromSymbol": "",
	//         "size": "11.64958799",
	//         "ts": "1700729673028",
	//         "clientOid": "1111506298504744960",
	//         "transferId": "24930940"
	//     }
	//
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var timestamp *int64 = this.SafeInteger(transfer, "ts")
	var status *string = this.SafeStringLower(transfer, "status")
	var currencyId *string = this.SafeString(transfer, "coin")
	var fromAccountRaw *string = this.SafeString(transfer, "fromType")
	var accountsById map[string]any = SafeMapTyped(this.Options, "accountsById")
	var fromAccount *string = this.SafeString(accountsById, fromAccountRaw, fromAccountRaw)
	var toAccountRaw *string = this.SafeString(transfer, "toType")
	var toAccount *string = this.SafeString(accountsById, toAccountRaw, toAccountRaw)
	return map[string]any{
		"info":        transfer,
		"id":          this.SafeString(transfer, "transferId"),
		"timestamp":   timestamp,
		"datetime":    this.Iso8601(timestamp),
		"currency":    this.SafeCurrencyCode(currencyId, currency),
		"amount":      this.SafeNumber(transfer, "size"),
		"fromAccount": fromAccount,
		"toAccount":   toAccount,
		"status":      this.ParseTransferStatus(status),
	}
}
func (this *Bitget) ParseTransferStatus(status *string) *string {
	var statuses map[string]any = map[string]any{
		"successful": "ok",
	}
	return this.SafeString(statuses, status, status)
}
func (this *Bitget) ParseDepositWithdrawFee(fee any, optionalArgs ...any) any {
	//
	//     {
	//         "chains": [
	//             {
	//                 "browserUrl": "https://blockchair.com/bitcoin/transaction/",
	//                 "chain": "BTC",
	//                 "depositConfirm": "1",
	//                 "extraWithdrawFee": "0",
	//                 "minDepositAmount": "0.0001",
	//                 "minWithdrawAmount": "0.005",
	//                 "needTag": "false",
	//                 "rechargeable": "true",
	//                 "withdrawConfirm": "1",
	//                 "withdrawFee": "0.0004",
	//                 "withdrawable": "true"
	//             },
	//         ],
	//         "coin": "BTC",
	//         "coinId": "1",
	//         "transfer": "true""
	//     }
	//
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var chains []any = SafeListTyped(fee, "chains")
	var chainsLength int = len(chains)
	var result map[string]any = map[string]any{
		"info": fee,
		"withdraw": map[string]any{
			"fee":        nil,
			"percentage": nil,
		},
		"deposit": map[string]any{
			"fee":        nil,
			"percentage": nil,
		},
		"networks": map[string]any{},
	}
	for i := 0; i < chainsLength; i++ {
		var chain map[string]any = MapTyped(func() any {
			if i >= 0 && i < len(chains) {
				return DerefScalar(chains[i])
			}
			return nil
		}())
		var networkId *string = this.SafeString(chain, "chain")
		var currencyCode *string = this.SafeString(currency, "code")
		var networkCode *string = this.NetworkIdToCode(networkId, currencyCode)
		if networkCode != nil {
			AddElementToObject(result["networks"], networkCode, map[string]any{
				"deposit": map[string]any{
					"fee":        nil,
					"percentage": nil,
				},
				"withdraw": map[string]any{
					"fee":        this.SafeNumber(chain, "withdrawFee"),
					"percentage": false,
				},
			})
		}
		if chainsLength == 1 {
			AddElementToObject(result["withdraw"], "fee", this.SafeNumber(chain, "withdrawFee"))
			AddElementToObject(result["withdraw"], "percentage", false)
		}
	}
	return result
}

