/**
 * @method
 * @name bitget#fetchBorrowInterest
 * @description fetch the interest owed by the user for borrowing currency for margin trading
 * @see https://www.bitget.com/api-doc/margin/cross/record/Get-Cross-Interest-Records
 * @see https://www.bitget.com/api-doc/margin/isolated/record/Get-Isolated-Interest-Records
 * @param {string} [code] unified currency code
 * @param {string} [symbol] unified market symbol when fetching interest in isolated markets
 * @param {int} [since] the earliest time in ms to fetch borrow interest for
 * @param {int} [limit] the maximum number of structures to retrieve
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {boolean} [params.paginate] default false, when true will automatically paginate by calling this endpoint multiple times. See in the docs all the [available parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
 * @returns {object[]} a list of [borrow interest structures]{@link https://docs.ccxt.com/?id=borrow-interest-structure}
 */
func (this *Bitget) FetchBorrowInterestAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchBorrowInterestBody(ch, optionalArgs...)
	return ch
}
func (this *Bitget) fetchBorrowInterestBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var code *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = code
	var symbol *string = GetArgStringPtr(optionalArgs, 1, nil)
	_ = symbol
	var since *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 3, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 4, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var paginate bool = false
	var paginateparamsVariable []any = this.HandleOptionAndParams(params, "fetchBorrowInterest", "paginate")
	paginate = GetValueBool(paginateparamsVariable, 0, false)
	params = MapTyped(GetValue(paginateparamsVariable, 1))
	if paginate {

		var retRes1114019 []any = ListTyped(PanicOnError((<-this.FetchPaginatedCallCursorAsync("fetchBorrowInterest", symbol, since, limit, params, "minId", "idLessThan"))))
		ch <- BoxAbsent(retRes1114019)
		return nil
	}
	var market map[string]any = nil
	if symbol != nil {
		market = this.Market(symbol)
	}
	var request map[string]any = map[string]any{}
	var currency map[string]any = nil
	if code != nil {
		currency = MapTyped(this.Currency(code))
		request["coin"] = GetValue(currency, "id")
	}
	if since != nil {
		request["startTime"] = since
	} else {
		request["startTime"] = this.Milliseconds() - 7776000000
	}
	if limit != nil {
		request["limit"] = limit
	}
	var response map[string]any = nil
	var marginMode any = nil
	var marginModeparamsVariable []any = this.HandleMarginModeAndParams("fetchBorrowInterest", params, "cross")
	marginMode = GetValue(marginModeparamsVariable, 0)
	params = MapTyped(GetValue(marginModeparamsVariable, 1))
	if IsEqual(marginMode, "isolated") {
		if symbol == nil {
			panic(ArgumentsRequired(this.Id + " fetchBorrowInterest() requires a symbol argument"))
		}
		request["symbol"] = this.SafeString(market, "id")

		response = MapTyped(PanicOnError((<-this.PrivateMarginGetV2MarginIsolatedInterestHistory(this.Extend(request, params))).Raw))
	} else if IsEqual(marginMode, "cross") {

		response = MapTyped(PanicOnError((<-this.PrivateMarginGetV2MarginCrossedInterestHistory(this.Extend(request, params))).Raw))
	}
	//
	// isolated
	//
	//     {
	//         "code": "00000",
	//         "msg": "success",
	//         "requestTime": 1700879935189,
	//         "data": {
	//             "resultList": [
	//                 {
	//                     "interestId": "1112125304879067137",
	//                     "interestCoin": "USDT",
	//                     "dailyInterestRate": "0.00041095",
	//                     "loanCoin": "USDT",
	//                     "interestAmount": "0.0000685",
	//                     "interstType": "first",
	//                     "symbol": "BTCUSDT",
	//                     "cTime": "1700877255648",
	//                     "uTime": "1700877255648"
	//                 },
	//             ],
	//             "maxId": "1112125304879067137",
	//             "minId": "1100138015672119298"
	//         }
	//     }
	//
	// cross
	//
	//     {
	//         "code": "00000",
	//         "msg": "success",
	//         "requestTime": 1700879597044,
	//         "data": {
	//             "resultList": [
	//                 {
	//                     "interestId": "1112122013642272769",
	//                     "interestCoin": "USDT",
	//                     "dailyInterestRate": "0.00041",
	//                     "loanCoin": "USDT",
	//                     "interestAmount": "0.00006834",
	//                     "interstType": "first",
	//                     "cTime": "1700876470957",
	//                     "uTime": "1700876470957"
	//                 },
	//             ],
	//             "maxId": "1112122013642272769",
	//             "minId": "1096917004629716993"
	//         }
	//     }
	//
	var data map[string]any = SafeMapTyped(response, "data")
	var rows []any = SafeListTypedDefault(data, "resultList", []any{})
	var interest any = this.ParseBorrowInterests(rows, market)

	ch <- this.FilterByCurrencySinceLimit(interest, code, since, limit)
	return nil
}
func (this *Bitget) ParseBorrowInterest(info any, optionalArgs ...any) any {
	//
	// isolated
	//
	//     {
	//         "interestId": "1112125304879067137",
	//         "interestCoin": "USDT",
	//         "dailyInterestRate": "0.00041095",
	//         "loanCoin": "USDT",
	//         "interestAmount": "0.0000685",
	//         "interstType": "first",
	//         "symbol": "BTCUSDT",
	//         "cTime": "1700877255648",
	//         "uTime": "1700877255648"
	//     }
	//
	// cross
	//
	//     {
	//         "interestId": "1112122013642272769",
	//         "interestCoin": "USDT",
	//         "dailyInterestRate": "0.00041",
	//         "loanCoin": "USDT",
	//         "interestAmount": "0.00006834",
	//         "interstType": "first",
	//         "cTime": "1700876470957",
	//         "uTime": "1700876470957"
	//     }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var marketId *string = this.SafeString(info, "symbol")
	market = MapTyped(this.SafeMarket(marketId, market))
	var marginMode string = func() string {
		if marketId != nil {
			return "isolated"
		}
		return "cross"
	}()
	var timestamp *int64 = this.SafeInteger(info, "cTime")
	return map[string]any{
		"info":           info,
		"symbol":         this.SafeString(market, "symbol"),
		"currency":       this.SafeCurrencyCode(this.SafeString(info, "interestCoin")),
		"interest":       this.SafeNumber(info, "interestAmount"),
		"interestRate":   this.SafeNumber(info, "dailyInterestRate"),
		"amountBorrowed": nil,
		"marginMode":     marginMode,
		"timestamp":      timestamp,
		"datetime":       this.Iso8601(timestamp),
	}
}

